from task_bootstrap import *
from analyze_timing import header_requests
import numpy as np
def quantile(v):return dict(n=len(v),p50=float(np.quantile(v,.5)),p90=float(np.quantile(v,.9)),p95=float(np.quantile(v,.95)),max=max(v)) if v else None
def analyze(id):
 path=STUDY/'output'/(id+'_RESULT.json');r=json.loads(path.read_text());folder=STUDY/'source/results'/id;summary=json.loads((folder/'summary.json').read_text()) if (folder/'summary.json').exists() else {};requests=summary.get('timing',{}).get('requests',[])
 if not requests and (folder/'runtime_artifacts.json.gz').exists():requests=header_requests(folder/'runtime_artifacts.json.gz')
 p=STUDY/'output'/(id+'_TIMING_PROFILE.json');prof=json.loads(p.read_text()) if p.exists() else {};task=[q for q in requests if q.get('stage')=='TASK'];fields=['acquisition_to_request_ms','snapshot_ms','queue_ms','compute_ms','worker_to_main_scheduling_ms','validation_and_command_construction_ms','activation_age_ms','disposition_age_ms'];st=STUDY/'output'/(id+'_SELECTIONS.json');sels=json.loads(st.read_text()).get('rows',[]) if st.exists() else [];cache=STUDY/'output'/(id+'_CERTIFICATE_REUSE.json');cr=json.loads(cache.read_text())['rows'] if cache.exists() else []
 out=dict(id=id,inputs=r['inputs'],worker_status=r['status'],valid=r.get('metric',{}).get('valid',False),abort_reason=summary.get('abort_reason'),task_request_count=len(task),full_timelines=task,stage_quantiles={k:quantile([q[k] for q in task if q.get(k) is not None]) for k in fields},activation_count=sum(q.get('outcome')=='ACTIVATED' for q in task),over_55_activated=sum(q.get('activation_age_ms',0)>55 for q in task if q.get('activation_age_ms') is not None),over_100_activated=sum(q.get('activation_age_ms',0)>=100 for q in task if q.get('activation_age_ms') is not None),outcome_reasons=[(q.get('outcome'),q.get('reason')) for q in task],profile_summary=prof.get('summary'),coordinator_ms=quantile([s['end_to_end_s']*1000 for s in sels]),fast_scientific_prefix_ms=quantile([s.get('fast_coordinator_s',s['end_to_end_s'])*1000 for s in sels]),late_discard=sum(s.get('late_discard',False) for s in sels),learning_selection_changes=sum(s.get('plan_changed',False) for s in sels),certificate_reuse_hits=sum(e['decision_reused'] for e in cr),certificate_reuse_reasons=[e['reason'] for e in cr],summary_keys=list(summary),metric=r.get('metric',{}))
 return out
def main():
 prefix=sys.argv[1] if len(sys.argv)>1 else '';rows=[analyze(p.stem[:-7]) for p in sorted((STUDY/'output').glob(prefix+'*_RESULT.json'))];save(STUDY/'reports'/('CAUSAL_TIMING'+('_'+prefix if prefix else '')+'.json'),dict(rows=rows,bridge_ms=40,evaluator_activation_ms=55,generic_expiry_ms=100,epoch_not_frozen_for_REALTIME_CHARACTERIZATION=True))
 for r in rows:print(json.dumps({k:r[k] for k in ('id','valid','abort_reason','stage_quantiles','coordinator_ms','fast_scientific_prefix_ms','late_discard','certificate_reuse_hits','certificate_reuse_reasons')}))
if __name__=='__main__':main()
